g=[[7]*16 for _ in range(16)]
segments={9:[[(r, c) for r,c in zip(range(4,10),range(8,14))],[(r,c) for r,c in zip(range(2,8),range(10,16))]],1:[[(r,c) for r,c in zip(range(6,12),range(6,12))]],3:[[(r,c) for r,c in zip(range(8,14),range(4,10))],[(r,c) for r,c in zip(range(10,16),range(2,8))]]}
for color, groups in segments.items():
    for cells in groups:
        for r,c in cells:g[r][c]=color
print('\n'.join(' '.join(map(str,row)) for row in g))
print('row lengths:', [len(row) for row in g])
